ref_dict.thm:selmer_erdos_kac_prime:
\begin{theorem}\label{thm:selmer_erdos_kac_prime}
	Consider the family of elliptic curves $E$ over a number field $K$ with level structure $G=G(M,MN)$. Let $\Phi$ be a subgroup of $\Z/M\Z$ of prime order, and let $m$ be as in Table \ref{tab:mean_variance_II}. Let $\sG = \sG_m(K)$ denote the subgroup 
\begin{equation}
	\{a\in (\Z/m\Z)^\times : \exists \text{ infinitely many degree one primes $\p$ with } N_{K/\Q}(\p)\equiv a \pmod{m}\}.
\end{equation}
	Let $c_{\E}(G,\Phi,\sG)$ and $\c_{\V}(G,\Phi,sG)$ be the constants in Table \ref{tab:mean_variance_II}. 
	Then the logarithmic Selmer ratios $s(E)$ are normally distributed with mean
	\begin{equation}
		c_{\E}(G,\Phi,\sG)\log\log(B)+O(1)
	\end{equation}
	and variance
	\begin{equation}
		c_{\V}(G,\Phi,\sG)\log\log(B)+O(1).
	\end{equation}
\end{theorem}

ref_dict.prop:elliptic_count_general:
\begin{proposition}\label{prop:elliptic_count_general}
Let $G\leq \GL_2(\Z/N\Z)$, and suppose that the modular curve $\cX_G$ is isomorphic to the weighted projective stack $\cP(w_0,w_1)$ over the number field $K$. 
Let $\delta(G)$ denote the weighted degree of the morphism $\phi_{O}:\cX_G\to\cX(1)$ that forgets the level structure, and suppose that $\gcd(w_0w_1, \delta(G))=1$. Define
\begin{equation}
 \alpha(G)\defeq\frac{w_0+w_1}{12 \delta(G)}\qquad \text{ and }\qquad
 \beta(G)\defeq \frac{\deg_{\Q}(K)-\min\{w_0,w_1\}}{12\delta(G)\deg_{\Q}(K)}.
 \end{equation}
Let $v\in \Val_0(K)$ be a finite place not above $2$ or $3$, and let $\Omega_v\subseteq\cP(w_0,w_1)(K_v)$ be a subset for which $\Omega_v^{\aff}$ is measurable and whose boundary has measure $m_v(\partial \Omega_v^{\aff})=0$. 
Then there exists an explicit constant $\kappa_G$, depending only on $G$ and $K$, such that
\begin{equation}
\cN_G(K,\Omega_v; B) 
 = m_v\left(\Omega_v^{\aff}\cap \cO_{K,v}^{2}\right)\kappa_G B^{\alpha(G)}
  + O\left(B^{\beta(G)}\right).
\end{equation}
\end{proposition}

