\begin{equation}\label{eq:main2}
	\limsup_{B\to\infty} \frac{1}{\# \cE_{G}(B; K)} \sum_{E\in \cE_{G}(B;K)} \# \Sel_p(E) \gg \log(B)^{\theta(G, \Phi, \sG_m(K))}.
\end{equation}
